#### MP4Read (src/mp4.cpp:90)

```cpp
MP4FileHandle MP4Read( const char* fileName, ShouldParseAtomCallback cb/*=nullptr*/ )
{
    if (!fileName)
        return MP4_INVALID_FILE_HANDLE;

    MP4File *pFile = ConstructMP4File();
    if (!pFile)
        return MP4_INVALID_FILE_HANDLE;

    try
    {
        ASSERT(pFile);

        if ( cb != nullptr )
           pFile->SetShouldParseAtomCallback( cb );

        pFile->Read( fileName, NULL );
        return (MP4FileHandle)pFile;
    }
    catch( Exception* x ) {
        mp4v2::impl::log.errorf(*x);
        delete x;
    }
    catch( ... ) {
        mp4v2::impl::log.errorf("%s: \"%s\": failed", __FUNCTION__,
                                fileName );
    }

    if (pFile)
        delete pFile;
    return MP4_INVALID_FILE_HANDLE;
}
```

#### mp4TrackIdsOfAllVideoTracks (mp4v2-Win/runner/runner.cpp:22)

```cpp
std::vector<MP4TrackId> mp4TrackIdsOfAllVideoTracks( MP4FileHandle handle )
{
   std::vector<MP4TrackId> trackIds;
   uint32_t numTracks = ::MP4GetNumberOfTracks( handle );
   for ( uint32_t trackIndex = 0; trackIndex < numTracks; ++trackIndex )
   {
      MP4TrackId trackId = ::MP4FindTrackId( handle, (uint16_t)trackIndex );
      if ( isVideoTrack( handle, trackId ) )
         trackIds.push_back( trackId );
   }
   return trackIds;
}
