29: bool MP4NameFirstMatches(const char* s1, const char* s2)
30: {
31:     if (s1 == NULL || *s1 == '\0' || s2 == NULL || *s2 == '\0') {
32:         return false;
33:     }
34: 
35:     if (*s2 == '*') {
36:         return true;
37:     }
38: 
39:     while (*s1 != '\0') {
40:         if (*s2 == '\0' || strchr("[.", *s2)) {
41:             break;
42:         }
43:         if (tolower(*s1) != tolower(*s2)) {
44:             return false;
45:         }
46:         s1++;
47:         s2++;
48:     }
49: 
50:     // Make sure we finished the loop by using up s2, not s1
51:     if ( *s2 != '[' && *s2 != '.' && *s2 != '\0' ) {
52:         return false;
53:     }
54: 
55:     return true;
56: }
