176: static bool convertBase64 (const char data, uint8_t *value)
177: {
178:     static const uint8_t decodingarr64[128] = {
179:         0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
180:         0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
181:         0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
182:         0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
183:         0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
184:         0xff, 0xff, 0xff, 0x3e, 0xff, 0xff, 0xff, 0x3f,
185:         0x34, 0x35, 0x36, 0x37, 0x38, 0x39, 0x3a, 0x3b,
186:         0x3c, 0x3d, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
187:         0xff, 0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06,
188:         0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e,
189:         0x0f, 0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16,
190:         0x17, 0x18, 0x19, 0xff, 0xff, 0xff, 0xff, 0xff,
191:         0xff, 0x1a, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f, 0x20,
192:         0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27, 0x28,
193:         0x29, 0x2a, 0x2b, 0x2c, 0x2d, 0x2e, 0x2f, 0x30,
194:         0x31, 0x32, 0x33, 0xff, 0xff, 0xff, 0xff, 0xff,
195:     };
196:     uint8_t index = (uint8_t)data;
197:     if ((index & 0x80) != 0) return false;
198: 
199:     if (decodingarr64[index] == 0xff) return false;
200:     *value = decodingarr64[index];
201:     return true;
