204: uint8_t *Base64ToBinary (const char *pData, uint32_t decodeSize, uint32_t *pDataSize)
205: {
206:     uint8_t *ret;
207:     uint32_t size, ix, groups;
208:     if (pData == NULL ||  decodeSize == 0 || pDataSize == NULL)
209:         return NULL;
210: 
211:     if ((decodeSize % 4) != 0) {
212:         // must be multiples of 4 characters
213:         return NULL;
214:     }
215:     size = (decodeSize * 3) / 4;
216:     groups = decodeSize / 4;
217:     ret = (uint8_t *)MP4Calloc(size);
218:     if (ret == NULL) return NULL;
219:     for (ix = 0; ix < groups; ix++) {
220:         uint8_t value[4];
221:         for (uint8_t jx = 0; jx < 4; jx++) {
222:             if (pData[jx] == '=') {
223:                 if (ix != (groups - 1)) {
224:                     free(ret);
225:                     return NULL;
226:                 }
227:                 size--;
228:                 value[jx] = 0;
229:             } else if (convertBase64(pData[jx], &value[jx]) == false) {
230:                 free(ret);
231:                 return NULL;
232:             }
233:         }
234:         ret[(ix * 3)] = value[0] << 2 | ((value[1] >> 4) & 0x3);
235:         ret[(ix * 3) + 1] = (value[1] << 4) | (value[2] >> 2 & 0xf);
236:         ret[(ix * 3) + 2] = ((value[2] & 0x3) << 6) | value[3];
237:         pData += 4;
238:     }
239:     *pDataSize = size;
240:     return ret;
241: }
