243: // log2 of value, rounded up
244: static uint8_t ilog2(uint64_t value)
245: {
246:     uint64_t powerOf2 = 1;
247:     for (uint8_t i = 0; i < 64; i++) {
248:         if (value <= powerOf2) {
249:             return i;
250:         }
251:         powerOf2 <<= 1;
252:     }
253:     return 64;
254: }
