256: uint64_t MP4ConvertTime(uint64_t t,
257:                         uint32_t oldTimeScale, uint32_t newTimeScale)
258: {
259:     // avoid float point exception
260:     if (oldTimeScale == 0) {
261:         throw new Exception("division by zero", __FILE__, __LINE__, __FUNCTION__ );
262:     }
263: 
264:     if (oldTimeScale == newTimeScale) return t;
265: 
266:     // check if we can safely use integer operations
267:     if (ilog2(t) + ilog2(newTimeScale) <= 64) {
268:         return (t * newTimeScale) / oldTimeScale;
269:     }
270: 
271:     // final resort is to use floating point
272:     double d = (double)newTimeScale;
273:     d *= double(t);
274:     d /= (double)oldTimeScale;
275:     d += 0.5; // round up.
276: 
277:     return (uint64_t)d;
278: }
