320: MP4Timestamp MP4GetAbsTimestamp() {
321:     /* MP4 epoch is midnight, January 1, 1904
322:      * offset from midnight, January 1, 1970 is 2082844800 seconds
323:      * 208284480 is (((1970 - 1904) * 365) + 17) * 24 * 60 * 60
